export const icon = (name, size=20) => `<svg class="icon" width="${Number(size)||20}" height="${Number(size)||20}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.star}"/></svg>`;
export function fmtDate(value,options={}) {if(!value)return '';const date=/^\d{4}-\d{2}-\d{2}$/.test(value)?new Date(value+'T12:00:00'):new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'short',...options}).format(date);}
export function fmtTime(value){if(/^\d{2}:\d{2}$/.test(value||''))return value;const date=new Date(value);return Number.isNaN(date.getTime())?'':new Intl.DateTimeFormat('de-DE',{hour:'2-digit',minute:'2-digit',timeZone:'Europe/Berlin'}).format(date);}
export const nameOf = (state,id) => state.members.find(m=>m.id===id)?.name || 'Noch nicht vergeben';
export function avatar(member,size=''){const name=member?.name||'?';const initials=name.split(/\s+/).slice(0,2).map(s=>s[0]).join('').toUpperCase();const color=/^#[\da-f]{6}$/i.test(member?.color||'')?member.color:'#718774';return `<span class="avatar ${h(size)}" style="--member-color:${color}" aria-hidden="true">${h(initials)}</span>`;}
